/* ---------- 04 approval ---------- */
const ap = $('#ap');
const qs = [
  { q:'How should the hero be structured?', o:[['Product screenshot','Shows the UI first'],['Short demo loop','Motion, under 10 seconds'],['Headline only','Fastest to load']] },
  { q:'Which sections go below the fold?', o:[['Features and proof','Standard order'],['Proof first','Logos and case studies'],['Pricing first','For returning visitors']] },
  { q:'Where should the main CTA point?', o:[['Book a call','Calendar embed'],['Start free','Sign-up form'],['Watch demo','Video modal']] }
];
let apI = 0, apSel = [];
function buildAp(){
  if (apI >= qs.length){
    ap.innerHTML = `<div class="ap-done enter"><span class="nbox" style="color:var(--success)">${ic('check_circle','icon-in')}</span><div><div class="n-title">Answers saved</div><div class="mono-xs">Starting the hero draft</div></div><button class="btn" id="ap-reset">Start over</button></div>`;
    $('#ap-reset').addEventListener('click', () => { Sound.play('tab'); apI = 0; apSel = []; morph(ap, buildAp); });
    return;
  }
  const cur = qs[apI];
  ap.innerHTML = `<div class="enter"><div class="ap-q">${cur.q}</div><div class="ap-opts" role="radiogroup">` +
    cur.o.map((o, i) => `<div class="ap-opt hatch"><button class="node" role="radio" aria-checked="false" data-i="${i}"><span class="key">${i+1}</span><span><span class="lbl">${o[0]}</span><span class="hint">${o[1]}</span></span></button></div>`).join('') +
    `</div><div class="ap-foot"><span class="mono-xs">${apI+1} / ${qs.length}</span><div class="ap-btns"><button class="btn" id="ap-skip">Skip</button><button class="btn primary" id="ap-next" disabled>Continue</button></div></div></div>`;
  $$('.ap-opt .node', ap).forEach(b => b.addEventListener('click', () => choose(+b.dataset.i)));
  $('#ap-skip').addEventListener('click', () => { Sound.play('tab'); apI++; morph(ap, buildAp); });
  $('#ap-next').addEventListener('click', () => { if (apSel[apI] == null) return; apI++; Sound.play(apI >= qs.length ? 'done' : 'tab'); morph(ap, buildAp); });
  if (apSel[apI] != null) choose(apSel[apI], true);
}
function choose(i, silent){
  apSel[apI] = i;
  $$('.ap-opt', ap).forEach((w, j) => { const on = j === i; w.classList.toggle('on', on); const n = w.querySelector('.node'); n.classList.toggle('on', on); n.setAttribute('aria-checked', on); });
  $('#ap-next').disabled = false;
  if (!silent) Sound.play('select');
}
document.addEventListener('keydown', e => {
  if (e.target.matches('textarea,input')) return;
  const r = $('#c4').getBoundingClientRect(); if (r.bottom < 0 || r.top > innerHeight) return;
  if (apI < qs.length && ['1','2','3'].includes(e.key)) choose(+e.key - 1);
});
buildAp();
